INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m30', 'intermediate', '権限', 'Cloudnest', '中村 / PdM', '/assets/avatars/nakamura.svg', '管理ロール', '一般社員に請求情報を見せたくありません。権限分けできますか？', 'ロールを分けます。請求タブは管理者だけに閉じます。', 'ろーるをわけます。せいきゅうたぶはかんりしゃだけにとじます。', '[{"text":"ロールを分けます。","kana":"ろーるをわけます。"},{"text":"請求タブは管理者だけに閉じます。","kana":"せいきゅうたぶはかんりしゃだけにとじます。"}]');
