INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m33', 'intermediate', 'bug', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'お知らせ一覧', '下書きが本番に出ている、と先方から電話がありました。', '公開フラグを先に確認します。出ていれば即非公開にしてご連絡します。', 'こうかいふらぐをさきにかくにんします。でていればそくひこうかいにしてごれんらくします。', '[{"text":"公開フラグを先に確認します。","kana":"こうかいふらぐをさきにかくにんします。"},{"text":"出ていれば即非公開にしてご連絡します。","kana":"でていればそくひこうかいにしてごれんらくします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m34', 'intermediate', '見積もり', 'Pencil Studio', '佐々木 / PM', '/assets/avatars/sasaki.svg', '多言語対応', '英語ページも欲しいと言われました。ざっくり金額だけ欲しいです。', '先に見積もりを出します。翻訳原稿があるかどうかで大きく変わります。', 'さきにみつもりをだします。ほんやくげんこうがあるかどうかでおおきくかわります。', '[{"text":"先に見積もりを出します。","kana":"さきにみつもりをだします。"},{"text":"翻訳原稿があるかどうかで大きく変わります。","kana":"ほんやくげんこうがあるかどうかでおおきくかわります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m35', 'intermediate', '仕様変更', '合同会社 Mintpath', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'カードUI', 'ホバーで拡大はやめて、影だけにしてほしいです。', '影だけに変えます。この部分は追加対応にはなりません。', 'かげだけにかえます。このぶぶんはついかたいおうにはなりません。', '[{"text":"影だけに変えます。","kana":"かげだけにかえます。"},{"text":"この部分は追加対応にはなりません。","kana":"このぶぶんはついかたいおうにはなりません。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m36', 'intermediate', '500', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', '画像アップロード', '大きい画像を上げると 500 になります。Issue #88 です。', 'Issue #88 を見ます。サイズ上限を入れて、失敗時の文言も足します。', 'Issue #88 をみます。さいずじょうげんをいれて、しっぱいじのもんごんもたします。', '[{"text":"Issue #88 を見ます。","kana":"Issue #88 をみます。"},{"text":"サイズ上限を入れて、失敗時の文言も足します。","kana":"さいずじょうげんをいれて、しっぱいじのもんごんもたします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m37', 'intermediate', 'CSV', '青木事務所', '青木 / 事務', '/assets/avatars/aoki.svg', '勤怠取込', 'CSV 取込で1行目がヘッダー扱いされないことがあります。', '1行目の判定を直します。サンプルファイルを1つください。', '1ぎょうめのはんていをなおします。さんぷるふぁいるを1つください。', '[{"text":"1行目の判定を直します。","kana":"1ぎょうめのはんていをなおします。"},{"text":"サンプルファイルを1つください。","kana":"さんぷるふぁいるを1つください。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m38', 'intermediate', '顧客説明', '山田商店', '山田 / 店主', '/assets/avatars/yamada.svg', '在庫同期', '在庫の反映に時間がかかる理由を、短く教えてください。', 'まとめて更新しているため、数分ずれることがあります。即時には変えられます。', 'まとめてこうしんしているため、すうふんずれることがあります。そくじにはかえられます。', '[{"text":"まとめて更新しているため、数分ずれることがあります。","kana":"まとめてこうしんしているため、すうふんずれることがあります。"},{"text":"即時には変えられます。","kana":"そくじにはかえられます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m39', 'intermediate', 'LP', '森カフェ', '森 / 店主', '/assets/avatars/mori.svg', 'ランチ告知', 'ランチの写真、もう少し明るくできますか？今週の掲示に使いたいです。', '明るくした版を今日中に試せそうです。気に入らなければ元に戻します。', 'あかるくしたばんをきょうじゅうにためせそうです。きにいらなければもとにもどします。', '[{"text":"明るくした版を今日中に試せそうです。","kana":"あかるくしたばんをきょうじゅうにためせそうです。"},{"text":"気に入らなければ元に戻します。","kana":"きにいらなければもとにもどします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('m40', 'intermediate', 'SEO', '株式会社 Harbor', '渡辺 / マーケ', '/assets/avatars/watanabe.svg', 'メタ整備', 'メタディスクリプションが空のページがあります。一覧はシートの B 列です。', 'B 列のページから埋めます。長いものは 80 字を目安に切ります。', 'B れつのぺーじからうめます。ながいものは 80 じをめやすにきります。', '[{"text":"B 列のページから埋めます。","kana":"B れつのぺーじからうめます。"},{"text":"長いものは","kana":"ながいものは"},{"text":" 80 字を目安に切ります。","kana":" 80 じをめやすにきります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a01', 'advanced', '緊急', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', '管理画面 500', '本番の管理画面が 500 です。今すぐ見てもらえますか？金曜夕方ですみません。', '今から見ます。500 のログと API を先に当たります。切り分けでき次第、復旧手順を共有します。', 'いまからみます。500 のろぐと API をさきにあたります。きりわけできしだい、ふっきゅうてじゅんをきょうゆうします。', '[{"text":"今から見ます。","kana":"いまからみます。"},{"text":"500 のログと API を先に当たります。","kana":"500 のろぐと API をさきにあたります。"},{"text":"切り分けでき次第、復旧手順を共有します。","kana":"きりわけできしだい、ふっきゅうてじゅんをきょうゆうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a02', 'advanced', 'PR', '合同会社 Lumio', '高橋 / 広報', '/assets/avatars/takahashi.svg', 'お知らせ API', 'PR #128 と Issue #42、どちらを先にマージしますか？リリースは今夜です。', 'Issue #42 を先に main へ入れます。PR #128 はレビュー後、v1.2 に間に合わせます。', 'Issue #42 をさきに main へいれます。PR #128 はれびゅーご、v1.2 にまにあわせます。', '[{"text":"Issue #42 を先に","kana":"Issue #42 をさきに"},{"text":" main へ入れます。","kana":" main へいれます。"},{"text":"PR #128 はレビュー後、v1.2 に間に合わせます。","kana":"PR #128 はれびゅーご、v1.2 にまにあわせます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a03', 'advanced', 'DB', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', '注文検索', '管理画面の検索がタイムアウトします。お客様対応が止まっています。', 'DB の遅いクエリを特定します。一時的に条件を絞る案内を出して、インデックス追加後に再デプロイします。', 'DB のおそいくえりをとくていします。いちじてきにじょうけんをしぼるあんないをだして、いんでっくすついかごにさいでぷろいします。', '[{"text":"DB の遅いクエリを特定します。","kana":"DB のおそいくえりをとくていします。"},{"text":"一時的に条件を絞る案内を出して、インデックス追加後に再デプロイします。","kana":"いちじてきにじょうけんをしぼるあんないをだして、いんでっくすついかごにさいでぷろいします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a04', 'advanced', '権限', 'グリーン企画', '伊藤 / 制作進行', '/assets/avatars/ito.svg', '権限まわり', '一般ユーザーに CSV 出力を出してよいか、先方に確認中です。実装は進めますか？', 'UI は進めます。CSV 出力はフラグで閉じておき、許可が出てから API を開きます。', 'UI はすすめます。CSV しゅつりょくはふらぐでとじておき、きょかがでてから API をひらきます。', '[{"text":"UI は進めます。","kana":"UI はすすめます。"},{"text":"CSV 出力はフラグで閉じておき、許可が出てから","kana":"CSV しゅつりょくはふらぐでとじておき、きょかがでてから"},{"text":" API を開きます。","kana":" API をひらきます。"}]');
