INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a12', 'advanced', 'webhook', 'Kite Inc.', '藤田 / エンジニア', '/assets/avatars/fujita.svg', '決済webhook', '決済 webhook が 2 重に来て、注文が二重登録されています。', '同じ ID は 1 回だけ処理するよう直します。重複分は手動で取り消して一覧を送ります。', 'おなじ ID は 1 かいだけしょりするようなおします。ちょうふくぶんはしゅどうでとりけしていちらんをおくります。', '[{"text":"同じ ID は 1 回だけ処理するよう直します。","kana":"おなじ ID は 1 かいだけしょりするようなおします。"},{"text":"重複分は手動で取り消して一覧を送ります。","kana":"ちょうふくぶんはしゅどうでとりけしていちらんをおくります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a13', 'advanced', 'staging', 'Cloudnest', '中村 / PdM', '/assets/avatars/nakamura.svg', '権限リリース', 'ステージングは通ったので、本番へ出してよいですか？ロール変更ありです。', '念のためバックアップを取ってから作業します。ロール変更後に管理者ログインだけ先に確認します。', 'ねんのためばっくあっぷをとってからさぎょうします。ろーるへんこうごにかんりしゃろぐいんだけさきにかくにんします。', '[{"text":"念のためバックアップを取ってから作業します。","kana":"ねんのためばっくあっぷをとってからさぎょうします。"},{"text":"ロール変更後に管理者ログインだけ先に確認します。","kana":"ろーるへんこうごにかんりしゃろぐいんだけさきにかくにんします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a14', 'advanced', 'production', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'キャッシュ障害', '本番だけ古い CSS が出ています。ステージングは新しいです。お客様から指摘が来ました。', '本番のキャッシュを切ります。ステージングが新しいなら成果物自体は問題なさそうです。反映後にスクショを送ります。', 'ほんばんのきゃっしゅをきります。すてーじんぐがあたらしいならせいかぶつじたいはもんだいなさそうです。はんえいごにすくしょをおくります。', '[{"text":"本番のキャッシュを切ります。","kana":"ほんばんのきゃっしゅをきります。"},{"text":"ステージングが新しいなら成果物自体は問題なさそうです。","kana":"すてーじんぐがあたらしいならせいかぶつじたいはもんだいなさそうです。"},{"text":"反映後にスクショを送ります。","kana":"はんえいごにすくしょをおくります。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a15', 'advanced', 'Git', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', 'ホットフィックス', 'hotfix を main に直接出してよいですか？develop はまだレビュー中です。', 'いったん main には入れずに、hotfix 枝から出します。あとで develop へ戻して PR を出します。', 'いったん main にはいれずに、hotfix えだからだします。あとで develop へもどして PR をだします。', '[{"text":"いったん main には入れずに、hotfix 枝から出します。","kana":"いったん main にはいれずに、hotfix えだからだします。"},{"text":"あとで develop へ戻して PR を出します。","kana":"あとで develop へもどして PR をだします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a16', 'advanced', 'PR', 'Kite Inc.', '藤田 / エンジニア', '/assets/avatars/fujita.svg', 'レビュー lag', 'PR #201 が 2 日止まっています。v1.2 に含めたいです。@tanaka にも見てもらえますか？', 'PR #201 を今日見ます。@tanaka にも依頼しておきます。指摘が少なければ午後までにマージします。', 'PR #201 をきょうみます。@tanaka にもいらいしておきます。してきがすくなければごごまでにまーじします。', '[{"text":"PR #201 を今日見ます。","kana":"PR #201 をきょうみます。"},{"text":"@tanaka にも依頼しておきます。","kana":"@tanaka にもいらいしておきます。"},{"text":"指摘が少なければ午後までにマージします。","kana":"してきがすくなければごごまでにまーじします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a17', 'advanced', 'SQL', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', '集計ずれ', '売上集計が管理画面と CSV で違います。経営会議が明日 10 時です。', '集計 SQL と CSV の条件を突き合わせます。税込か税抜かの差が多いです。明日の午前中に共有します。', 'しゅうけい SQL と CSV のじょうけんをつきあわせます。ぜいこみかぜいぬきかのさがおおいです。あしたのごぜんちゅうにきょうゆうします。', '[{"text":"集計","kana":"しゅうけい"},{"text":" SQL と CSV の条件を突き合わせます。","kana":" SQL と CSV のじょうけんをつきあわせます。"},{"text":"税込か税抜かの差が多いです。明日の午前中に共有します。","kana":"ぜいこみかぜいぬきかのさがおおいです。あしたのごぜんちゅうにきょうゆうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a18', 'advanced', '認証', 'Cloudnest', '中村 / PdM', '/assets/avatars/nakamura.svg', '権限昇格', '一般ユーザーが管理者画面を開けた、という報告があります。今すぐ見てください。', '権限チェックを先に見ます。開けていれば即閉じます。影響範囲はログから洗い出します。', 'けんげんちぇっくをさきにみます。あけていればそくとじます。えいきょうはんいはろぐからあらいだします。', '[{"text":"権限チェックを先に見ます。","kana":"けんげんちぇっくをさきにみます。"},{"text":"開けていれば即閉じます。","kana":"あけていればそくとじます。"},{"text":"影響範囲はログから洗い出します。","kana":"えいきょうはんいはろぐからあらいだします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a19', 'advanced', '見積もり', 'Pencil Studio', '佐々木 / PM', '/assets/avatars/sasaki.svg', '大規模追加', '会員ランクとクーポンを足したいです。工期と概算を先にください。仕様はまだ粗いです。', '先に見積もりを出します。仕様が粗いので、前提を箇条書きにして金額の幅も書きます。', 'さきにみつもりをだします。しようがあらいので、ぜんていをかじょうがきにしてきんがくのはばもかきます。', '[{"text":"先に見積もりを出します。","kana":"さきにみつもりをだします。"},{"text":"仕様が粗いので、前提を箇条書きにして金額の幅も書きます。","kana":"しようがあらいので、ぜんていをかじょうがきにしてきんがくのはばもかきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a20', 'advanced', 'デザイン', '合同会社 Mintpath', '加藤 / デザイナー', '/assets/avatars/kato.svg', 'デザインシステム', 'ボタンをすべて `--brand` に寄せたいです。例外はエラーだけ残してください。', '通常ボタンは `--brand` に揃えます。エラーだけ赤を残します。差分は PR にスクショ付きで出します。', 'つうじょうぼたんは `--brand` にそろえます。えらーだけあかをのこします。さぶんは PR にすくしょつきでだします。', '[{"text":"通常ボタンは `--brand` に揃えます。","kana":"つうじょうぼたんは `--brand` にそろえます。"},{"text":"エラーだけ赤を残します。","kana":"えらーだけあかをのこします。"},{"text":"差分は PR にスクショ付きで出します。","kana":"さぶんは PR にすくしょつきでだします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a21', 'advanced', 'release', 'グリーン企画', '伊藤 / 制作進行', '/assets/avatars/ito.svg', 'リリースノート', 'リリースノート、`## 変更点` と `- 修正` の形で明日までに欲しいです。', '`## 変更点` の形でまとめます。`- 修正` と `- 追加` に分けます。', '`## へんこうてん` のけいでまとめます。`- しゅうせい` と `- ついか` にわけます。', '[{"text":"`## 変更点` の形でまとめます。","kana":"`## へんこうてん` のけいでまとめます。"},{"text":"`- 修正` と","kana":"`- しゅうせい` と"},{"text":" `- 追加` に分けます。","kana":" `- ついか` にわけます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a22', 'advanced', '障害', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', '在庫API', '在庫 API がタイムアウトして、カートが進めません。売上に直結しています。', '在庫 API のタイムアウトを先に見ます。一時的にキャッシュを長くして、復旧後に戻します。', 'ざいこ API のたいむあうとをさきにみます。いちじてきにきゃっしゅをながくして、ふっきゅうごにもどします。', '[{"text":"在庫 API のタイムアウトを先に見ます。","kana":"ざいこ API のたいむあうとをさきにみます。"},{"text":"一時的にキャッシュを長くして、復旧後に戻します。","kana":"いちじてきにきゃっしゅをながくして、ふっきゅうごにもどします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a23', 'advanced', 'deploy', 'Kite Inc.', '藤田 / エンジニア', '/assets/avatars/fujita.svg', 'デプロイ失敗', 'デプロイが途中で落ちました。本番は旧版のままです。再実行してよいですか？', '旧版のままなら再実行してよいです。失敗ログを見て、マイグレーションが途中でないことだけ確認します。', 'きゅうばんのままならさいじっこうしてよいです。しっぱいろぐをみて、まいぐれーしょんがとちゅうでないことだけかくにんします。', '[{"text":"旧版のままなら再実行してよいです。","kana":"きゅうばんのままならさいじっこうしてよいです。"},{"text":"失敗ログを見て、マイグレーションが途中でないことだけ確認します。","kana":"しっぱいろぐをみて、まいぐれーしょんがとちゅうでないことだけかくにんします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a24', 'advanced', '顧客説明', '山田商店', '山田 / 店主', '/assets/avatars/yamada.svg', '予約トラブル', '予約が二重に入った理由を、店のスタッフにも分かる言葉でください。', '同じ操作を短時間に 2 回したため、二重に入りました。今は 1 回だけ通るよう直しています。', 'おなじそうさをたんじかんに 2 かいしたため、にじゅうにはいりました。いまは 1 かいだけとおるようなおしています。', '[{"text":"同じ操作を短時間に 2 回したため、二重に入りました。","kana":"おなじそうさをたんじかんに 2 かいしたため、にじゅうにはいりました。"},{"text":"今は 1 回だけ通るよう直しています。","kana":"いまは 1 かいだけとおるようなおしています。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a25', 'advanced', '納期', 'Pencil Studio', '佐々木 / PM', '/assets/avatars/sasaki.svg', '年末リリース', '12/28 公開は厳しいですか？先方は年始キャンペーンに使いたいそうです。', '12/28 は品質的に厳しいです。1/6 公開なら安全に出せます。先方への言い方も添えます。', '12/28 はひんしつてきにきびしいです。1/6 こうかいならあんぜんにだせます。せんぽうへのいいかたもそえます。', '[{"text":"12/28 は品質的に厳しいです。","kana":"12/28 はひんしつてきにきびしいです。"},{"text":"1/6 公開なら安全に出せます。","kana":"1/6 こうかいならあんぜんにだせます。"},{"text":"先方への言い方も添えます。","kana":"せんぽうへのいいかたもそえます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a26', 'advanced', '追加料金', 'グリーン企画', '伊藤 / 制作進行', '/assets/avatars/ito.svg', '急な言語追加', '公開前日に中国語も、と言われました。やるなら追加料金で説明したいです。', '公開前日の追加は難しいです。この部分だけ追加対応になります。金額とリスクを短く書きます。', 'こうかいぜんじつのついかはむずかしいです。このぶぶんだけついかたいおうになります。きんがくとりすくをみじかくかきます。', '[{"text":"公開前日の追加は難しいです。","kana":"こうかいぜんじつのついかはむずかしいです。"},{"text":"この部分だけ追加対応になります。","kana":"このぶぶんだけついかたいおうになります。"},{"text":"金額とリスクを短く書きます。","kana":"きんがくとりすくをみじかくかきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a27', 'advanced', 'accessibility', '合同会社 Mintpath', '加藤 / デザイナー', '/assets/avatars/kato.svg', '監査前修正', '`aria-label` 抜けとコントラスト、まとめて直してもらえますか？監査が来週です。', '`aria-label` とコントラストを先に直します。監査前にチェックリストも添付します。', '`aria-label` とこんとらすとをさきになおします。かんさまえにちぇっくりすともてんぷします。', '[{"text":"`aria-label` とコントラストを先に直します。","kana":"`aria-label` とこんとらすとをさきになおします。"},{"text":"監査前にチェックリストも添付します。","kana":"かんさまえにちぇっくりすともてんぷします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a28', 'advanced', 'test', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', 'E2E不足', '決済の E2E が無くて不安です。最低限どれを足しますか？', '成功、失敗、二重送信の 3 本を足します。今夜 develop に出して、明日レビューお願いします。', 'せいこう、しっぱい、にじゅうそうしんの 3 ほんをたします。こんや develop にだして、あしたれびゅーおねがいします。', '[{"text":"成功、失敗、二重送信の 3 本を足します。","kana":"せいこう、しっぱい、にじゅうそうしんの 3 ほんをたします。"},{"text":"今夜 develop に出して、明日レビューお願いします。","kana":"こんや develop にだして、あしたれびゅーおねがいします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a29', 'advanced', '404', '株式会社 Northstar', '佐藤 / Web 担当', '/assets/avatars/sato.svg', 'リダイレクト漏れ', '旧 URL が 404 のままです。SEO 担当が焦っています。一覧はシートにあります。', 'シートの旧 URL を 301 で新 URL へ向けます。残件があれば別Issueに分けます。', 'しーとのきゅう URL を 301 でしん URL へむけます。ざんけんがあればべつIssueにわけます。', '[{"text":"シートの旧 URL を 301 で新 URL へ向けます。","kana":"しーとのきゅう URL を 301 でしん URL へむけます。"},{"text":"残件があれば別Issueに分けます。","kana":"ざんけんがあればべつIssueにわけます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a30', 'advanced', 'cache', 'Kite Inc.', '藤田 / エンジニア', '/assets/avatars/fujita.svg', 'パージ手順', 'キャッシュクリアの手順、運用に渡せる形で残してください。本番事故防止です。', '手順を `1. 確認 2. パージ 3. 再読込` で残します。間違えて全消ししない注意も書きます。', 'てじゅんを `1. かくにん 2. ぱーじ 3. さいよみこみ` でのこします。まちがえてぜんけししないちゅういもかきます。', '[{"text":"手順を","kana":"てじゅんを"},{"text":" `1. 確認 2. パージ 3. 再読込` で残します。","kana":" `1. かくにん 2. ぱーじ 3. さいよみこみ` でのこします。"},{"text":"間違えて全消ししない注意も書きます。","kana":"まちがえてぜんけししないちゅういもかきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a31', 'advanced', 'performance', 'Orion inc.', '田中 / エンジニア', '/assets/avatars/tanaka.svg', 'N+1', '商品詳細が遅いです。クエリログを添付しました。インデックスは既にあります。', '添付ログを見ると N+1 です。まとめ取得に変えて、ステージングで計測してから出します。', 'てんぷろぐをみると N+1 です。まとめしゅとくにかえて、すてーじんぐでけいそくしてからだします。', '[{"text":"添付ログを見ると N+1 です。","kana":"てんぷろぐをみると N+1 です。"},{"text":"まとめ取得に変えて、ステージングで計測してから出します。","kana":"まとめしゅとくにかえて、すてーじんぐでけいそくしてからだします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a32', 'advanced', 'browser', 'Shopfolio', '林 / EC 担当', '/assets/avatars/hayashi.svg', 'Safari崩れ', 'Safari だけ日付ピッカーが崩れます。Chrome は問題ありません。来週キャンペーンです。', 'Safari だけ再現します。ネイティブピッカーを避けて、同じ見た目に揃えます。キャンペーン前に出します。', 'Safari だけさいげんします。ねいてぃぶぴっかーをさけて、おなじみためにそろえます。きゃんぺーんまえにだします。', '[{"text":"Safari だけ再現します。","kana":"Safari だけさいげんします。"},{"text":"ネイティブピッカーを避けて、同じ見た目に揃えます。","kana":"ねいてぃぶぴっかーをさけて、おなじみためにそろえます。"},{"text":"キャンペーン前に出します。","kana":"きゃんぺーんまえにだします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a33', 'advanced', '保守', '青木事務所', '青木 / 事務', '/assets/avatars/aoki.svg', '月次点検', '月次点検の報告、経営向けに 5 行でください。障害は無かった想定です。', '障害なし、更新 3 件、バックアップ確認済み、で 5 行にまとめます。数字は管理画面から拾います。', 'しょうがいなし、こうしん 3 けん、ばっくあっぷかくにんずみ、で 5 ぎょうにまとめます。すうじはかんりがめんからひろいます。', '[{"text":"障害なし、更新 3 件、バックアップ確認済み、で 5 行にまとめます。","kana":"しょうがいなし、こうしん 3 けん、ばっくあっぷかくにんずみ、で 5 ぎょうにまとめます。"},{"text":"数字は管理画面から拾います。","kana":"すうじはかんりがめんからひろいます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a34', 'advanced', '打合せ', '株式会社 Harbor', '渡辺 / マーケ', '/assets/avatars/watanabe.svg', '施策会議', '来週の施策会議で、AB テスト結果を説明してください。資料は簡易でよいです。', '勝った案と理由を 1 枚にします。数字は管理画面の期間指定と揃えておきます。', 'かったあんとりゆうを 1 まいにします。すうじはかんりがめんのきかんしていとそろえておきます。', '[{"text":"勝った案と理由を","kana":"かったあんとりゆうを"},{"text":" 1 枚にします。","kana":" 1 まいにします。"},{"text":"数字は管理画面の期間指定と揃えておきます。","kana":"すうじはかんりがめんのきかんしていとそろえておきます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a35', 'advanced', 'スケジュール', 'Cloudnest', '中村 / PdM', '/assets/avatars/nakamura.svg', 'マイルストーン', 'マイルストーンを `M1 / M2 / M3` で引き直してください。先方が来週確認します。', '`M1 / M2 / M3` で引き直します。先方確認用に前提と残リスクも 3 行添えます。', '`M1 / M2 / M3` でひきなおします。せんぽうかくにんようにぜんていとざんりすくも 3 ぎょうそえます。', '[{"text":"`M1 / M2 / M3` で引き直します。","kana":"`M1 / M2 / M3` でひきなおします。"},{"text":"先方確認用に前提と残リスクも 3 行添えます。","kana":"せんぽうかくにんようにぜんていとざんりすくも 3 ぎょうそえます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a36', 'advanced', 'API', 'Kite Inc.', '藤田 / エンジニア', '/assets/avatars/fujita.svg', 'レートリミット', '外部 API が 429 を返すようになりました。リトライ方針を決めて実装してください。', '429 は待ってから最大 3 回リトライします。それでもダメなら 500 にせず、後で再実行します。', '429 はまってからさいだい 3 かいりとらいします。それでもだめなら 500 にせず、あとでさいじっこうします。', '[{"text":"429 は待ってから最大 3 回リトライします。","kana":"429 はまってからさいだい 3 かいりとらいします。"},{"text":"それでもダメなら 500 にせず、後で再実行します。","kana":"それでもだめなら 500 にせず、あとでさいじっこうします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a37', 'advanced', 'ログイン', 'Orion inc.', '鈴木 / 事業部', '/assets/avatars/suzuki.svg', 'セッション切れ', '操作中に突然ログイン画面へ戻されます。顧客説明用の一文もください。', '一定時間操作がないと安全のため切れます。再ログインすれば続きから戻れます、と案内できます。', 'いっていじかんそうさがないとあんぜんのためきれます。さいろぐいんすればつづきからもどれます、とあんないできます。', '[{"text":"一定時間操作がないと安全のため切れます。","kana":"いっていじかんそうさがないとあんぜんのためきれます。"},{"text":"再ログインすれば続きから戻れます、と案内できます。","kana":"さいろぐいんすればつづきからもどれます、とあんないできます。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a38', 'advanced', '進捗', 'Pencil Studio', '佐々木 / PM', '/assets/avatars/sasaki.svg', '大型改修', '先方に今週の進捗を送りたいです。できたこと / 残 / リスクの 3 点でください。', 'できたこと、残作業、リスクの 3 点で送ります。リスクはリリース週の仕様追加だけです。', 'できたこと、ざんさぎょう、りすくの 3 てんでおくります。りすくはりりーすしゅうのしようついかだけです。', '[{"text":"できたこと、残作業、リスクの 3 点で送ります。","kana":"できたこと、ざんさぎょう、りすくの 3 てんでおくります。"},{"text":"リスクはリリース週の仕様追加だけです。","kana":"りすくはりりーすしゅうのしようついかだけです。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a39', 'advanced', '障害', '森カフェ', '森 / 店主', '/assets/avatars/mori.svg', '予約ステータス', '予約が全部「仮」のままです。店が午後の準備に入れません。今から見てもらえますか？', '仮のまま固まる不具合です。今から直して、確定に戻します。戻し完了後にご連絡します。', 'かりのままかたまるふぐあいです。いまからなおして、かくていにもどします。もどしかんりょうごにごれんらくします。', '[{"text":"仮のまま固まる不具合です。","kana":"かりのままかたまるふぐあいです。"},{"text":"今から直して、確定に戻します。","kana":"いまからなおして、かくていにもどします。"},{"text":"戻し完了後にご連絡します。","kana":"もどしかんりょうごにごれんらくします。"}]');
INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a40', 'advanced', 'アクセス解析', '株式会社 Harbor', '渡辺 / マーケ', '/assets/avatars/watanabe.svg', '広告計測', '広告の CV が管理画面と合わず、出稿を止めるか判断したいです。今日中に切り分けできますか？', '広告側とサイト側の計測を一度切り分けます。ずれている期間が分かれば先に共有ください。今日中に結論を出します。', 'こうこくがわとさいとがわのけいそくをいちどきりわけます。ずれているきかんがわかればさきにきょうゆうください。きょうじゅうにけつろんをだします。', '[{"text":"広告側とサイト側の計測を一度切り分けます。","kana":"こうこくがわとさいとがわのけいそくをいちどきりわけます。"},{"text":"ずれている期間が分かれば先に共有ください。","kana":"ずれているきかんがわかればさきにきょうゆうください。"},{"text":"今日中に結論を出します。","kana":"きょうじゅうにけつろんをだします。"}]');
